// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns



// EVOLVE-BLOCK-START
const INSERTION_THRESHOLD: usize = 24;

pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    if n <= 1 { return; }
    if n <= INSERTION_THRESHOLD || is_nearly_sorted_adjacent(arr) {
        insertion_sort(arr);
    } else {
        arr.sort_unstable();
    }
}

// Count adjacent inversions; cheap signal for "almost sorted".
fn is_nearly_sorted_adjacent<T: Ord>(arr: &[T]) -> bool {
    let limit = arr.len() / 16 + 1;
    let mut bad = 0usize;
    for w in arr.windows(2) {
        if w[0] > w[1] {
            bad += 1;
            if bad > limit { return false; }
        }
    }
    true
}

fn insertion_sort<T: Ord>(a: &mut [T]) {
    for i in 1..a.len() {
        let p = a[..i].binary_search(&a[i]).unwrap_or_else(|p| p);
        a[p..=i].rotate_right(1);
    }
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut r = BenchmarkResults { times: vec![], correctness: vec![], adaptability_score: 0.0 };
    for data in test_data {
        let mut a = data.clone();
        let t = std::time::Instant::now();
        adaptive_sort(&mut a);
        r.times.push(t.elapsed().as_secs_f64());
        r.correctness.push(a.windows(2).all(|w| w[0] <= w[1]));
    }
    let n = r.times.len() as f64;
    if n > 1.0 {
        let s: f64 = r.times.iter().sum();
        let s2: f64 = r.times.iter().map(|t| t * t).sum();
        let var = (s2 / n - (s / n) * (s / n)).max(0.0);
        r.adaptability_score = 1.0 / (1.0 + var.sqrt());
    }
    r
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_sort() {
        let mut arr = vec![3, 1, 4, 1, 5, 9, 2, 6];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![1, 1, 2, 3, 4, 5, 6, 9]);
    }

    #[test]
    fn test_empty_array() {
        let mut arr: Vec<i32> = vec![];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![]);
    }

    #[test]
    fn test_single_element() {
        let mut arr = vec![42];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![42]);
    }
}
